CREATE TABLE IF NOT EXISTS public.installments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, contract_id uuid NOT NULL REFERENCES public.hire_purchase_contracts(id) ON DELETE CASCADE, installment_number integer NOT NULL CHECK (installment_number > 0), due_date date NOT NULL, amount numeric NOT NULL CHECK (amount >= 0), paid_amount numeric NOT NULL DEFAULT 0 CHECK (paid_amount >= 0), status text NOT NULL DEFAULT 'PENDING', paid_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(contract_id, installment_number));